INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Adapter-Pattern nur für Legacy-Systeme relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für neue Schnittstellen nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Adapter-Pattern?', 3, '[{"text": "Schnittstellenintegration", "correct": true, "because": "Passt inkompatible Interfaces an"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Adapter-Pattern?', 5, '[{"text": "Adapter", "correct": true, "because": "Vermittelt zwischen Schnittstellen"}, {"text": "Adaptee", "correct": true, "because": "Anzupassende Klasse"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Nicht Design-Pattern"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Adapter übersetzt Aufrufe. b) Er ersetzt das Adaptee.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Adaptee bleibt bestehen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Adapter-Pattern?', 4, '[{"text": "Schnittstellenkompatibilität", "correct": false, "because": "Kern des Patterns"}, {"text": "Adaptee-Funktionalität", "correct": false, "because": "Basis der Anpassung"}, {"text": "UI-Gestaltung", "correct": true, "because": "Kein Design-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Adapter auch ohne Interface funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Klassenadapter möglich"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend Interface nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Target im Adapter-Pattern?', 3, '[{"text": "Zielschnittstelle", "correct": true, "because": "Definiert erwartete Methoden"}, {"text": "Datenquelle", "correct": false, "because": "Adaptee ist Quelle"}, {"text": "UI-Komponente", "correct": false, "because": "Nicht UI-bezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Varianten gibt es beim Adapter-Pattern?', 5, '[{"text": "Klassenadapter", "correct": true, "because": "Vererbung nutzen"}, {"text": "Objektadapter", "correct": true, "because": "Komposition nutzen"}, {"text": "Datenflussadapter", "correct": false, "because": "Kein Pattern"}, {"text": "UI-Adapter", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Adapter verbindet Systeme. b) Er ändert die Adaptee-Logik. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logik bleibt unverändert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Adapter-Pattern?', 4, '[{"text": "Target-Interface", "correct": false, "because": "Definiert Ziel"}, {"text": "Adaptee", "correct": false, "because": "Anzupassende Klasse"}, {"text": "3D-Grafiken", "correct": true, "because": "Kein Pattern-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Adapter nur für alte Systeme?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für neue Schnittstellen"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum Adapter-Pattern?', 4, '[{"text": "Client", "correct": true, "because": "Nutzt die Schnittstelle"}, {"text": "Adapter", "correct": true, "because": "Vermittelt Aufrufe"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Adapter die Leistung senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Overhead meist minimal"}, {"text": "Ja", "correct": false, "because": "Abhängig von Implementierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Adapter-Pattern?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Schnittstellen angleichen"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Funktion zählt mehr"}, {"text": "UI-Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Adapter nutzt Komposition. b) Er erstellt neue Klassen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Er passt an, nicht neu"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Adapter-Pattern?', 5, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Alte Systeme nutzbar"}, {"text": "Flexibilität", "correct": true, "because": "Schnittstellen anpassbar"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Verbesserung", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Adapter-Pattern unwichtig?', 3, '[{"text": "Schnittstellenanpassung", "correct": false, "because": "Kern des Patterns"}, {"text": "Adaptee-Funktion", "correct": false, "because": "Basis der Anpassung"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann der Adapter mehrere Adaptees verbinden?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Komposition möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Adapter auch für neue Systeme nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Schnittstellenintegration generell"}, {"text": "Nein", "correct": false, "because": "Nicht nur Legacy"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Ziel-Schnittstelle?', 4, '[{"text": "Interface", "correct": true, "because": "Definiert erwartete Methoden"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "UI-Komponente", "correct": false, "because": "Nicht UI-bezogen"}]');
